/// `EVENT_LISTENERS` property.
fn desired_listeners(node: &HostNode) -> u32 {
    let mut mask = 0u32;
    if node.component_type == component_type::BUTTON {
        mask |= listener::POINTER_DOWN | listener::POINTER_MOVE | listener::POINTER_UP;
